plugins {
    id("org.jetbrains.kotlin.jvm") version "2.0.21"
    application
}

kotlin { jvmToolchain(17) }

// Generated by `uniffi-bindgen generate --language kotlin --out-dir core/bindings/kotlin` (see run.ps1).
sourceSets["main"].kotlin.srcDir("../../bindings/kotlin")

dependencies {
    implementation("net.java.dev.jna:jna:5.15.0")
}

application {
    mainClass = "SmokeKt"
}

tasks.named<JavaExec>("run") {
    // Directory holding tvbro_ffi.dll / libtvbro_ffi.so; passed by run.ps1.
    val lib = providers.gradleProperty("libDir").orElse(layout.projectDirectory.dir("../../target/debug").asFile.path)
    systemProperty("jna.library.path", lib.get())
}
